import { gunzipSync } from 'node:zlib';
import { extractAttachment } from '../vendor/pdf-library.mjs';

try {
  const chunks = [];
  let size = 0;
  for await (const chunk of process.stdin) {
    size += chunk.length;
    if (size > 65536) throw new Error('input too large');
    chunks.push(chunk);
  }
  const input = Buffer.concat(chunks);
  if (input.subarray(0, 7).toString() !== 'SHOPPDF') throw new Error('bad envelope');
  // Bound decompression before invoking the vendor API, which has no limit option.
  gunzipSync(input.subarray(7), { maxOutputLength: 1048576 });
  const xml = await extractAttachment(input);
  if (Buffer.byteLength(xml) > 1048576) throw new Error('output too large');
  process.stdout.write(xml);
} catch {
  process.exitCode = 1;
}

