import os, sys, time, signal
pid = int(sys.argv[1])
if sys.platform == 'darwin':
    import ctypes
    lib = ctypes.CDLL('/usr/lib/libproc.dylib')
    def rss():
        data = ctypes.create_string_buffer(96)
        if lib.proc_pidinfo(pid, 4, 0, data, len(data)) != len(data):
            raise RuntimeError('cannot inspect parser')
        return int.from_bytes(data.raw[8:16], sys.byteorder)
else:
    def rss():
        with open('/proc/%d/statm' % pid) as f:
            return int(f.read().split()[1]) * os.sysconf('SC_PAGE_SIZE')
try:
    if rss() > 96 * 1024 * 1024:
        raise RuntimeError('memory limit')
    print('ready', flush=True)
    while True:
        time.sleep(0.01)
        if rss() > 96 * 1024 * 1024:
            raise RuntimeError('memory limit')
except BaseException:
    try:
        os.kill(pid, signal.SIGKILL)
    except OSError:
        pass
    sys.exit(1)

