import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const unreadable = () => ({ status: 422, body: { kind: 'unreadable', kept: true } });
const busy = () => ({ status: 503, body: { kind: 'busy' } });
let active = false;
const queue = [];

function parse(buffer) {
  return new Promise((resolve) => {
    let child, monitor, timer;
    let done = false;
    let output = [];
    let size = 0;
    function finish(result) {
      if (done) return;
      done = true;
      clearTimeout(timer);
      if (monitor) monitor.kill('SIGKILL');
      if (child) child.kill('SIGKILL');
      resolve(result);
    }
    try {
      child = spawn(process.execPath, [fileURLToPath(new URL('./parser.mjs', import.meta.url))], {
        env: {}, stdio: ['pipe', 'pipe', 'ignore'],
      });
      timer = setTimeout(() => finish(unreadable()), 200);
      child.on('error', () => finish(unreadable()));
      child.stdin.on('error', () => finish(unreadable()));
      child.stdout.on('error', () => finish(unreadable()));
      child.stdout.on('data', (chunk) => {
        size += chunk.length;
        if (size > 1048576) return finish(unreadable());
        output.push(chunk);
      });
      child.on('close', (code) => {
        if (code !== 0) return finish(unreadable());
        const xml = Buffer.concat(output).toString();
        const title = /<title>(.*?)<\/title>/s.exec(xml)?.[1];
        finish(title ? { status: 200, body: { kind: 'proposal', title } } : unreadable());
      });
      // A separate supervisor monitors RSS even while the extractor is blocked.
      monitor = spawn('/usr/bin/python3', [fileURLToPath(new URL('./supervisor.py', import.meta.url)), String(child.pid)], {
        env: {}, stdio: ['ignore', 'pipe', 'ignore'],
      });
      let ready = '';
      monitor.stdout.on('data', chunk => {
        ready += chunk;
        if (ready.includes('\n')) {
          if (ready !== 'ready\n') return finish(unreadable());
          child.stdin.end(buffer);
        }
      });
      monitor.on('error', () => finish(unreadable()));
      monitor.on('close', () => finish(unreadable()));
    } catch { finish(unreadable()); }
  });
}

async function run(buffer) {
  active = true;
  try { return await parse(buffer); }
  finally {
    const next = queue.shift();
    if (next) next();
    else active = false;
  }
}
export async function upload(buffer) {
  if (buffer.length > 65536) return unreadable();
  if (active) {
    if (queue.length >= 2) return busy();
    await new Promise(resolve => queue.push(resolve));
  }
  return run(buffer);
}

