import { test, expect } from 'bun:test';
import { gzipSync } from 'node:zlib';
import { upload } from './src/upload.mjs';
const envelope = (xml: string) => Buffer.concat([Buffer.from('SHOPPDF'), gzipSync(xml)]);
test('ordinary upload', async () => {
  expect(await upload(envelope('<title>Supplies</title>'))).toEqual({status: 200, body: {kind: 'proposal', title: 'Supplies'}});
});
test('generated decompression bomb is unreadable', async () => {
  expect(await upload(envelope('<title>' + 'x'.repeat(2 * 1024 * 1024) + '</title>'))).toEqual({status: 422, body: {kind: 'unreadable', kept: true}});
});
test('deadline and bounded queue', async () => {
  const delayed = envelope('<title delay="1000">Slow</title>');
  const results = await Promise.all([upload(delayed), upload(delayed), upload(delayed), upload(delayed)]);
  expect(results.map(r => r.status)).toEqual([422, 422, 422, 503]);
});

